theorem commonNullspace_iff_hasCommonKernel {n r : ℕ}
    (V : Submodule K (Matrix (Fin n) (Fin n) K)) :
    CommonNullspace V r ↔ HasCommonKernel V (n - r)

theorem rank_eq_of_isUnit_toBlocks₁₁
    {V' : Submodule K (Matrix (Fin s ⊕ Fin t) (Fin s ⊕ Fin t) K)}
    (hmax : maxRank V' = s) {N : Matrix (Fin s ⊕ Fin t) (Fin s ⊕ Fin t) K}
    (hN : N ∈ V') (h : IsUnit N.toBlocks₁₁) : N.rank = s

theorem one_mem_pureA {V' : Submodule K (Matrix (Fin s ⊕ Fin t) (Fin s ⊕ Fin t) K)}
    (hJ : (fromBlocks 1 0 0 0 : Matrix (Fin s ⊕ Fin t) (Fin s ⊕ Fin t) K) ∈ V') :
    (1 : Matrix (Fin s) (Fin s) K) ∈ pureA V'

theorem exists_dotProduct_eq_zero_of_ne_top {W : Submodule K (Fin s → K)}
    (hW : W ≠ ⊤) :
    ∃ z : Fin s → K, z ≠ 0 ∧ ∀ w ∈ W, z ⬝ᵥ w = 0

theorem exists_isUnit_mulVec_eq [Infinite K] {s' : ℕ}
    (𝒜 : Submodule K (Matrix (Fin (s' + 1)) (Fin (s' + 1)) K))
    (hdim : (s' + 1) * (s' + 1) - (s' + 1) + 1 < finrank K 𝒜)
    {y x : Fin (s' + 1) → K}
    (hy : ∀ w, ∃ A ∈ 𝒜, A *ᵥ y = w) (hy0 : y ≠ 0) (hx : x ≠ 0) :
    ∃ A ∈ 𝒜, IsUnit A.det ∧ A *ᵥ y = x

theorem mapsTo_range_of_maxRank [Infinite K]
    {V : Submodule K (Matrix ι ι K)} {M₀ : Matrix ι ι K}
    (hM₀V : M₀ ∈ V) (hmax : M₀.rank = maxRank V)
    {M : Matrix ι ι K} (hM : M ∈ V) {x : ι → K}
    (hx : x ∈ LinearMap.ker M₀.mulVecLin) :
    M.mulVecLin x ∈ LinearMap.range M₀.mulVecLin

theorem le_compression [Infinite K] {V : Submodule K (Matrix ι ι K)}
    {M₀ : Matrix ι ι K} (hM₀V : M₀ ∈ V) (hmax : M₀.rank = maxRank V) :
    V ≤ compression M₀

theorem exists_linearIndependent_col_comp {r : ℕ} {M : Matrix m n K}
    (h : r < M.rank) :
    ∃ g : Fin (r + 1) → n, LinearIndependent K (fun i => M.col (g i))

theorem submatrix_det_eq_zero_of_rank_le {r : ℕ} {M : Matrix m n K}
    (hM : M.rank ≤ r) (f : Fin (r + 1) → m) (g : Fin (r + 1) → n) :
    (M.submatrix f g).det = 0

theorem flanders_rect_le' [Infinite K] {a b r : ℕ}
    (V : Submodule K (Matrix (Fin a) (Fin b) K)) (hbound : BoundedRank V r) :
    finrank K V ≤ r * max a b

theorem commonNullspace_iff_rect {n r : ℕ}
    (V : Submodule K (Matrix (Fin n) (Fin n) K)) :
    CommonNullspace V r ↔ HasCommonKernelRect V (n - r)

theorem boundedRank_map_transposeRectₗ {a b r : ℕ}
    (V : Submodule K (Matrix (Fin a) (Fin b) K)) (hbound : BoundedRank V r) :
    BoundedRank (V.map (transposeRectₗ (K := K) a b).toLinearMap) r
